package com.chatsystem.admin.ui.cell;

import com.chatsystem.shared.model.*; import com.chatsystem.shared.service.AdminService; import javafx.scene.control.*; import javafx.scene.layout.*; import java.util.function.LongConsumer;
public final class ModerationCaseCell extends ListCell<SpamReport>{private final AdminService service;private final LongConsumer open;public ModerationCaseCell(AdminService service,LongConsumer open){this.service=service;this.open=open;}@Override protected void updateItem(SpamReport report,boolean empty){super.updateItem(report,empty);if(empty||report==null){setGraphic(null);return;}Label caseId=field("WR-"+report.getId(),90);Label reason=field(report.getReason(),170);Label user=field(service.getUser(report.getReportedUserId()).map(UserAccount::getDisplayName).orElse("Unavailable"),150);Label context=field(service.getMessage(report.getMessageId()).flatMap(m->service.getGroup(m.getConversationId())).map(Conversation::getName).orElse("Private message"),150);Label created=field(report.getCreatedAt().toString(),180);Label status=field(report.getStatus().name(),100);status.getStyleClass().add(report.getStatus()==com.chatsystem.shared.model.status.ReportStatus.PENDING?"pill-warning":"pill-success");report.statusProperty().addListener((o,a,b)->status.setText(b.name()));Button inspect=new Button("Inspect");inspect.getStyleClass().add("small-button");inspect.setOnAction(e->open.accept(report.getId()));HBox row=new HBox(8,caseId,reason,user,context,created,status,inspect);row.getStyleClass().add("list-row");setGraphic(row);}private static Label field(String text,double width){Label label=new Label(text);label.setPrefWidth(width);label.setMaxWidth(width);return label;}}
